import{_ as d,o as e,c as r,a2 as o}from"./chunks/framework.C0pL2NcE.js";const u=JSON.parse('{"title":"4. Levels","description":"","frontmatter":{},"headers":[],"relativePath":"gdd/levels.md","filePath":"gdd/levels.md"}'),l={name:"gdd/levels.md"};function n(s,t,a,i,c,h){return e(),r("div",null,[...t[0]||(t[0]=[o('<h1 id="_4-levels" tabindex="-1">4. Levels <a class="header-anchor" href="#_4-levels" aria-label="Permalink to &quot;4. Levels&quot;">​</a></h1><p>Twenty pictures of 136 × 128-grain frames (grains of about 6 px); the game plays them from <code>src/game/level-edits.json</code> in the order below, named <code>level_1</code> to <code>level_20</code> in the game and in the Level Editor, whatever name a saved or imported copy carries (<code>GAME_ORDER</code> in <code>src/game/levels.ts</code>).</p><ul><li><strong>Level 1</strong> (<code>builtin-0</code>, formerly level 11) is the cherries, a small picture (3,602 grains, 3 colours).</li><li><strong>Levels 2–5</strong> (<code>builtin-12</code>, <code>builtin-10</code>, <code>builtin-11</code>, <code>builtin-13</code>) are full-frame scenes with zoomed grains (<strong>Phóng to hạt</strong>, ×1.25 to ×1.5), so they hold fewer grains (6,675 to 9,396) and show them bigger.</li><li><strong>Levels 6–11</strong> (<code>builtin-14</code> to <code>builtin-19</code>, formerly levels 5–10) are one subject on the empty frame (3,811 to 7,945 grains); <strong>level 12</strong> is the ice cream; <strong>levels 13–20</strong> are the full-frame scenes (about 17,000 grains). Levels with ids <code>builtin-10</code> to <code>builtin-19</code> exist only in <code>level-edits.json</code> (no older drawing in <code>levels.ts</code>).</li></ul><p>The game builds every level&#39;s nests (the hand-set ones were dropped when the grains grew, since the pictures&#39; blocks changed; make new ones with <strong>Tự sinh tổ kiến</strong>). Difficulty rises through picture size, number of colours and nest size (<code>chunk</code>, in blocks before the ×2 nest scale). Not yet checked with the test bot.</p><table tabindex="0"><thead><tr><th>#</th><th>Subject</th><th>Grains</th><th>Blocks</th><th>Colours</th><th>Chunk</th><th>Nests</th><th>Grain zoom</th></tr></thead><tbody><tr><td>1</td><td>Cherries</td><td>3,602</td><td>57</td><td>red, black, olivegreen</td><td>3–5</td><td>rows</td><td>—</td></tr><tr><td>2</td><td>Rocket</td><td>6,675</td><td>106</td><td>darkblue, white, red</td><td>3–5</td><td>rows</td><td>×1.51</td></tr><tr><td>3</td><td>Cat</td><td>7,566</td><td>119</td><td>white, darkblue, yellow</td><td>3–5</td><td>rows</td><td>×1.41</td></tr><tr><td>4</td><td>Castle</td><td>8,245</td><td>130</td><td>white, purple, yellow</td><td>3–5</td><td>rows</td><td>×1.41</td></tr><tr><td>5</td><td>Sailboat</td><td>9,396</td><td>148</td><td>teal, white, yellow</td><td>4–6</td><td>rows</td><td>×1.25</td></tr><tr><td>6</td><td>Tulips in a pot</td><td>5,513</td><td>87</td><td>orangered, pink, green, brown</td><td>4–6</td><td>rows</td><td>—</td></tr><tr><td>7</td><td>Whale</td><td>3,811</td><td>61</td><td>navy, teal, white</td><td>3–5</td><td>rows (3 columns)</td><td>—</td></tr><tr><td>8</td><td>Chick</td><td>4,917</td><td>78</td><td>yellow, brown, orangered</td><td>3–5</td><td>rows (3 columns)</td><td>—</td></tr><tr><td>9</td><td>Clownfish</td><td>6,384</td><td>102</td><td>orangered, purple, white</td><td>3–5</td><td>rows</td><td>—</td></tr><tr><td>10</td><td>Octopus</td><td>6,921</td><td>111</td><td>magenta, purple, white, skyblue</td><td>4–6</td><td>rows</td><td>—</td></tr><tr><td>11</td><td>Ladybug on a leaf</td><td>7,945</td><td>126</td><td>green, black, red, white</td><td>4–6</td><td>rows</td><td>—</td></tr><tr><td>12</td><td>Ice cream</td><td>3,528</td><td>56</td><td>pink, black, yellow</td><td>4–6</td><td>rows</td><td>—</td></tr><tr><td>13</td><td>Rocket</td><td>16,999</td><td>268</td><td>navy, white, lightyellow, red</td><td>4–6</td><td>rows</td><td>—</td></tr><tr><td>14</td><td>Sleeping cat with flowers</td><td>17,000</td><td>268</td><td>olivegreen, white, yellowgreen, yellow</td><td>4–6</td><td>rows, seed 5</td><td>—</td></tr><tr><td>15</td><td>Black cat peeking</td><td>17,000</td><td>268</td><td>yellow, cyan, black, white, olivegreen, yellowgreen</td><td>5–8</td><td>onion</td><td>—</td></tr><tr><td>16</td><td>Sailboat</td><td>17,000</td><td>268</td><td>cyan, white, navy, orangered</td><td>4–6</td><td>rows, seed 3</td><td>—</td></tr><tr><td>17</td><td>Sea turtle</td><td>17,000</td><td>268</td><td>navy, cyan, white, red</td><td>4–6</td><td>rows</td><td>—</td></tr><tr><td>18</td><td>Panda</td><td>17,000</td><td>267</td><td>olivegreen, yellowgreen, white, yellow</td><td>4–6</td><td>rows</td><td>—</td></tr><tr><td>19</td><td>Cottage with garden</td><td>17,000</td><td>268</td><td>white, pink, olivegreen, black</td><td>4–7</td><td>rows</td><td>—</td></tr><tr><td>20</td><td>Toucan</td><td>17,000</td><td>269</td><td>yellowgreen, lightorange, cyan, navy, lightyellow</td><td>5–8</td><td>rows, seed 6</td><td>—</td></tr></tbody></table><h2 id="design-rules" tabindex="-1">Design rules <a class="header-anchor" href="#design-rules" aria-label="Permalink to &quot;Design rules&quot;">​</a></h2><p>The full rules for drawing, colouring and building levels are in <a href="./level-design">5. Level design rules</a>.</p><ul><li><p><strong>One area per colour:</strong> keep each colour in one area of the picture. A colour that runs from top to bottom (for example one body colour around the whole picture) makes nests that cannot fill until the very end, and the conveyor overflows.</p></li><li><p><strong>Make and check levels in the Level Editor:</strong> it turns an image into a sand picture in the game&#39;s colours and builds nests that a recorded play wins (see the <a href="./../guide/level-editor">Level Editor guide</a>).</p></li></ul>',8)])])}const w=d(l,[["render",n]]);export{u as __pageData,w as default};
